    <section class="card patient-list-toolbar" aria-label="Visit filters"><form method="get" action="<?= current_url() ?>" class="patient-filter-form"><input type="hidden" name="view" value="<?= esc($filters['view']) ?>"><div class="patient-filter-search"><label class="sr-only" for="patient-visit-search">Search visits</label><i class="bi bi-search" aria-hidden="true"></i><input id="patient-visit-search" class="form-control" type="search" name="search" value="<?= esc($filters['search']) ?>" placeholder="Doctor, visit, appointment, service or diagnosis"></div><select class="form-control form-control-sm" name="status" aria-label="Visit status"><option value="">All statuses</option><?php foreach (['draft', 'completed', 'cancelled'] as $option): ?><option value="<?= esc($option) ?>" <?= $filters['status'] === $option ? 'selected' : '' ?>><?= esc(ucwords(str_replace('_', ' ', $option))) ?></option><?php endforeach; ?></select><select class="form-control form-control-sm" name="doctor_id" aria-label="Doctor"><option value="">All doctors</option><?php foreach ($doctors as $doctor): ?><option value="<?= (int) $doctor['id'] ?>" <?= (string) $filters['doctor_id'] === (string) $doctor['id'] ? 'selected' : '' ?>>Dr. <?= esc(trim(($doctor['first_name'] ?? '') . ' ' . ($doctor['last_name'] ?? ''))) ?></option><?php endforeach; ?></select><select class="form-control form-control-sm" name="service" aria-label="Service"><option value="">All services</option><?php foreach ($services as $item): ?><option value="<?= esc($item['service_name']) ?>" <?= $filters['service'] === $item['service_name'] ? 'selected' : '' ?>><?= esc($item['service_name']) ?></option><?php endforeach; ?></select><select class="form-control form-control-sm" name="appointment_type" aria-label="Visit type"><option value="">All types</option><?php foreach (['in_person', 'online', 'home_visit'] as $option): ?><option value="<?= esc($option) ?>" <?= $filters['appointment_type'] === $option ? 'selected' : '' ?>><?= esc(ucwords(str_replace('_', ' ', $option))) ?></option><?php endforeach; ?></select><input class="form-control form-control-sm patient-date-filter" type="text" name="date_from" value="<?= esc($filters['date_from']) ?>" placeholder="From dd-mm-yyyy" aria-label="Visit date from"><input class="form-control form-control-sm patient-date-filter" type="text" name="date_to" value="<?= esc($filters['date_to']) ?>" placeholder="To dd-mm-yyyy" aria-label="Visit date to"><select class="form-control form-control-sm" name="page_size" aria-label="Page size"><?php foreach ([10, 15, 25, 50] as $size): ?><option value="<?= $size ?>" <?= (int) $filters['page_size'] === $size ? 'selected' : '' ?>><?= $size ?> / page</option><?php endforeach; ?></select><div class="patient-filter-actions"><button class="btn btn-primary btn-sm" type="submit"><i class="bi bi-funnel mr-1" aria-hidden="true"></i>Apply</button><a class="btn btn-light btn-sm" href="<?= current_url() ?>">Clear</a></div><div class="patient-view-toggle" role="group" aria-label="Visit view"><a class="btn btn-sm <?= $filters['view'] === 'list' ? 'btn-primary' : 'btn-outline-secondary' ?>" href="<?= current_url() . '?' . http_build_query(array_merge($filters, ['view' => 'list', 'page' => 1])) ?>" aria-pressed="<?= $filters['view'] === 'list' ? 'true' : 'false' ?>">List</a><a class="btn btn-sm <?= $filters['view'] === 'grid' ? 'btn-primary' : 'btn-outline-secondary' ?>" href="<?= current_url() . '?' . http_build_query(array_merge($filters, ['view' => 'grid', 'page' => 1])) ?>" aria-pressed="<?= $filters['view'] === 'grid' ? 'true' : 'false' ?>">Grid</a></div></form></section>
    <section class="card patient-visits-content"><div class="card-header d-flex flex-wrap align-items-center justify-content-between"><div><h2 class="h5 mb-1">Consultation records</h2><span class="small text-muted">Only patient-safe visit information is displayed.</span></div><span class="small text-muted"><i class="fa-solid fa-circle-exclamation mr-1" aria-hidden="true"></i>Created and updated metadata</span></div><?php if ($filters['view'] === 'grid'): ?><?= view(PATIENT_VIEW . 'pages/visits_grid', compact('visits')) ?><?php else: ?><?= view(PATIENT_VIEW . 'pages/visits_list', compact('visits')) ?><?php endif; ?></section>
    <?php $values = ['search' => $filters['search'], 'status' => $filters['status'], 'doctor_id' => $filters['doctor_id'], 'service' => $filters['service'], 'appointment_type' => $filters['appointment_type'], 'date_from' => $filters['date_from'], 'date_to' => $filters['date_to'], 'view' => $filters['view'], 'page_size' => $filters['page_size']]; ?><div class="card pagination-card mb-4"><div class="card-body py-3 d-flex flex-wrap align-items-center justify-content-between"><span class="small text-muted">Showing page <?= (int) $pagination['page'] ?> of <?= (int) $pagination['pages'] ?> · <?= (int) $pagination['total'] ?> visits</span><nav aria-label="Visit pagination"><?php $values['page'] = max(1, (int) $pagination['page'] - 1); ?><a class="btn btn-sm btn-outline-secondary <?= (int) $pagination['page'] <= 1 ? 'disabled' : '' ?>" href="<?= (int) $pagination['page'] > 1 ? esc(current_url() . '?' . http_build_query($values)) : '#' ?>">Previous</a><?php $values['page'] = min((int) $pagination['pages'], (int) $pagination['page'] + 1); ?><a class="btn btn-sm btn-outline-secondary <?= (int) $pagination['page'] >= (int) $pagination['pages'] ? 'disabled' : '' ?>" href="<?= (int) $pagination['page'] < (int) $pagination['pages'] ? esc(current_url() . '?' . http_build_query($values)) : '#' ?>">Next</a></nav></div></div>
    <div class="modal fade patient-visit-modal" id="patient-visit-detail-modal" tabindex="-1" role="dialog" aria-labelledby="patient-visit-detail-title" aria-hidden="true"><div class="modal-dialog modal-dialog-scrollable modal-lg" role="document"><div class="modal-content"><div class="modal-header"><div><span class="patient-eyebrow">Patient-safe visit</span><h2 class="modal-title h5" id="patient-visit-detail-title">Visit Details</h2></div><button class="close" type="button" data-dismiss="modal" aria-label="Close"><span aria-hidden="true">&times;</span></button></div><div class="modal-body" id="patient-visit-detail-body" aria-live="polite"><div class="patient-modal-loading" role="status"><span class="spinner-border spinner-border-sm mr-2" aria-hidden="true"></span>Loading visit details…</div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-dismiss="modal">Close</button></div></div></div></div>
