<?= $this->section('scripts') ?><script>
    $(function () {
        var records = <?= json_encode($visits, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) ?>;
        var escapeHtml = function (value) { return $('<div>').text(value == null ? '' : value).html(); };
        $('.patient-date-filter').datepicker({ format: 'dd-mm-yyyy', autoclose: true, todayHighlight: true, orientation: 'bottom auto', container: '.patient-visits-page' });
        $(document).on('show.bs.dropdown.patientVisits', '.patient-visits-page .dropdown', function () { var dropdown = $(this); var menu = dropdown.children('.dropdown-menu'); if (! menu.length) return; menu.data('patient-dropdown-parent', dropdown).appendTo('body'); });
        $(document).on('hidden.bs.dropdown.patientVisits', '.patient-visits-page .dropdown', function () { var dropdown = $(this); var menu = $('body > .dropdown-menu').filter(function () { var parent = $(this).data('patient-dropdown-parent'); return parent && parent.is(dropdown); }).first(); if (menu.length) menu.appendTo(dropdown).removeData('patient-dropdown-parent'); });
        $(document).on('click.patientVisitDetails', '.patient-visit-view', function () { var visit = records.find(function (item) { return Number(item.id) === Number($(this).data('id')); }.bind(this)); var body = $('#patient-visit-detail-body'); body.html('<div class="patient-modal-loading" role="status"><span class="spinner-border spinner-border-sm mr-2" aria-hidden="true"></span>Loading visit details…</div>'); if (! visit) { body.html('<div class="patient-modal-state patient-modal-state-error" role="alert">Visit details could not be found.</div>'); return; } $('#patient-visit-detail-title').text('Visit Details · ' + (visit.consultation_number || '—')); body.html('<section class="patient-modal-section"><h3><i class="bi bi-clipboard2-pulse mr-2" aria-hidden="true"></i>Visit summary</h3><div class="patient-detail-grid"><div><span>Visit number</span><strong>' + escapeHtml(visit.consultation_number || '—') + '</strong></div><div><span>Date / time</span><strong>' + escapeHtml((visit.visit_date_display || '—') + ' · ' + (visit.visit_time_display || '—')) + '</strong></div><div><span>Appointment</span><strong>' + escapeHtml(visit.appointment_number || 'Not linked') + '</strong></div><div><span>Status / type</span><strong>' + escapeHtml((visit.status_label || '—') + ' · ' + (visit.type_label || '—')) + '</strong></div></div></section><section class="patient-modal-section"><h3><i class="bi bi-person-badge mr-2" aria-hidden="true"></i>Doctor and service</h3><div class="patient-detail-grid"><div><span>Doctor</span><strong>Dr. ' + escapeHtml((visit.doctor_first_name || '') + ' ' + (visit.doctor_last_name || '')) + '</strong></div><div><span>Specialization</span><strong>' + escapeHtml(visit.specialization || 'Not recorded') + '</strong></div><div class="patient-detail-wide"><span>Service</span><strong>' + escapeHtml(visit.service_display || 'Consultation') + '</strong></div></div></section>' + (visit.diagnosis_summary ? '<section class="patient-modal-section"><h3><i class="bi bi-file-medical mr-2" aria-hidden="true"></i>Clinical summary</h3><p class="mb-0">' + escapeHtml(visit.diagnosis_summary) + '</p></section>' : '') + '<section class="patient-modal-section"><h3><i class="bi bi-link-45deg mr-2" aria-hidden="true"></i>Related records</h3><div class="patient-detail-grid"><div><span>Prescription</span><strong>' + (visit.prescription_id > 0 ? '<a href="<?= base_url('patient/prescriptions') ?>?prescription_id=' + Number(visit.prescription_id) + '">View prescription</a>' : 'Not available') + '</strong></div><div><span>Invoice / payment</span><strong>' + (visit.invoice_id > 0 ? '<a href="<?= base_url('patient/invoices') ?>?invoice_id=' + Number(visit.invoice_id) + '">View invoice</a>' : 'Not available') + '</strong></div><div><span>Follow-up</span><strong>' + escapeHtml(visit.follow_up_date_display || 'Not scheduled') + '</strong></div></div></section><p class="patient-modal-metadata"><i class="fa-solid fa-circle-exclamation mr-1" aria-hidden="true"></i>Created: ' + escapeHtml(visit.created_at || '—') + '<br>Updated: ' + escapeHtml(visit.updated_at || '—') + '</p>'); });
    });
</script><?= $this->endSection() ?>
